def adjacent_product(values):
    if len(values) < 2:
        raise ValueError("at least two values required")
    best = values[0] * values[1]
    for i in range(1, len(values) - 1):
        best = max(best, values[i] * values[i + 1])
    return best

def move_zeros(values):
    write = 0
    for value in values:
        if value != 0:
            values[write] = value
            write += 1
    for i in range(write, len(values)):
        values[i] = 0
    return values

from collections import Counter

def first_unique(text):
    counts = Counter(text)
    return next((char for char in text if counts[char] == 1), None)

from collections import Counter

def is_anagram(left, right):
    return Counter(left) == Counter(right)
